SELECT CAST(COUNT(CASE WHEN l.charttime BETWEEN a.admittime AND a.admittime + INTERVAL '72 hours' THEN 1 END) AS FLOAT) / NULLIF(COUNT(a.subject_id), 0) AS proportion_within_72h, CAST(COUNT(CASE WHEN l.charttime BETWEEN a.dischtime - INTERVAL '24 hours' AND a.dischtime THEN 1 END) AS FLOAT) / NULLIF(COUNT(a.subject_id), 0) AS proportion_within_24h, COUNT(CASE WHEN l.charttime BETWEEN a.admittime AND a.dischtime THEN 1 END) AS total_events, COUNT(CASE WHEN l.charttime BETWEEN a.admittime AND a.dischtime - INTERVAL '24 hours' THEN 1 END) AS events_before_24h, COUNT(CASE WHEN l.charttime BETWEEN a.admittime + INTERVAL '72 hours' AND a.dischtime THEN 1 END) AS events_after_72h, (COUNT(CASE WHEN l.charttime BETWEEN a.admittime AND a.dischtime THEN 1 END) - COUNT(CASE WHEN l.charttime BETWEEN a.admittime + INTERVAL '72 hours' AND a.dischtime THEN 1 END)) AS difference_events, (COUNT(CASE WHEN l.charttime BETWEEN a.admittime AND a.dischtime - INTERVAL '24 hours' THEN 1 END) - COUNT(CASE WHEN l.charttime BETWEEN a.admittime AND a.dischtime THEN 1 END)) AS difference_events_before_24h, (COUNT(CASE WHEN l.charttime BETWEEN a.admittime + INTERVAL '72 hours' AND a.dischtime THEN 1 END) - COUNT(CASE WHEN l.charttime BETWEEN a.admittime AND a.dischtime THEN 1 END)) AS difference_events_after_72h FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN labevents l ON a.subject_id = l.subject_id WHERE p.gender = 'M' AND p.anchor_age = 62 AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 57 AND 67 AND l.itemid = 757071 AND l.value = 'GLP-1';